class TextCategorizer:
    def __init__(self):
        # Initialize sets for each category
        self.uppercase_letters = set()
        self.lowercase_letters = set()
        self.digits = set()
        self.symbols = set()
        # Overall total characters processed
        self.total_characters = 0

    def add_text(self, text):
        """Accepts a new string, updates categorical sets and character counts."""
        for char in text:
            self.total_characters += 1
            if char.isupper():
                self.uppercase_letters.add(char)
            elif char.islower():
                self.lowercase_letters.add(char)
            elif char.isdigit():
                self.digits.add(char)
            else:
                # Consider anything not alphanumeric a symbol
                self.symbols.add(char)

    # Set operations for uppercase letters
    def uppercase_union(self, other):
        return self.uppercase_letters.union(other.uppercase_letters)

    def uppercase_intersection(self, other):
        return self.uppercase_letters.intersection(other.uppercase_letters)

    def uppercase_difference(self, other):
        return self.uppercase_letters.difference(other.uppercase_letters)

    # Set operations for lowercase letters
    def lowercase_union(self, other):
        return self.lowercase_letters.union(other.lowercase_letters)

    def lowercase_intersection(self, other):
        return self.lowercase_letters.intersection(other.lowercase_letters)

    def lowercase_difference(self, other):
        return self.lowercase_letters.difference(other.lowercase_letters)

    # Set operations for digits
    def digits_union(self, other):
